#include "stdlib/blas/base/dspmv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Performs the matrix-vector operation `Y = alpha*A*X + beta*Y` where `alpha` and `beta` are scalars, `X` and `Y` are `N` element vectors, and `A` is an `N` by `N` symmetric matrix supplied in packed form.
*
* @param order    storage layout
* @param uplo     specifies whether the upper or lower triangular part of the symmetric matrix `A` is supplied
* @param N        number of elements along each dimension of `A`
* @param alpha    scalar constant
* @param AP       packed form of a symmetric matrix `A`
* @param X        first input array
* @param strideX  `X` stride length
* @param beta     scalar constant
* @param Y        second input array
* @param strideY  `Y` stride length
* @return         output value
*/
void API_SUFFIX(c_dspmv)( const CBLAS_LAYOUT order, const CBLAS_UPLO uplo, const CBLAS_INT N, const double alpha, const double *AP, const double *X, const CBLAS_INT strideX, const double beta, double *Y, const CBLAS_INT strideY ) {
	CBLAS_INT offsetX;
	CBLAS_INT offsetY;

	// Perform input argument validation...
	if ( order != CblasRowMajor && order != CblasColMajor ) {
		c_xerbla( 1, "c_dspmv", "Error: invalid argument. First argument must be a valid storage layout. Value: `%d`.", order );
		return;
	}
	if ( uplo != CblasUpper && uplo != CblasLower ) {
		c_xerbla( 2, "c_dspmv", "Error: invalid argument. Second argument must be a either upper or lower. Value: `%d`.", uplo );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 3, "c_dspmv", "Error: invalid argument. Third argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	if ( strideX == 0 ) {
		c_xerbla( 7, "c_dspmv", "Error: invalid argument. Seventh argument must be a nonzero. Value: `%d`.", strideX );
		return;
	}
	if ( strideY == 0 ) {
		c_xerbla( 10, "c_dspmv", "Error: invalid argument. Tenth argument must be a nonzero. Value: `%d`.", strideY );
		return;
	}
	offsetX = stdlib_strided_stride2offset( N, strideX );
	offsetY = stdlib_strided_stride2offset( N, strideY );
	API_SUFFIX(c_dspmv_ndarray)( order, uplo, N, alpha, AP, 0, X, strideX, offsetX, beta, Y, strideY, offsetY );
	return;
}
